<script setup lang="ts">
definePageMeta({ layout: 'dashboard', middleware: 'admin' }); useSeoMeta({ title: 'Utilisateurs', robots: 'noindex' })
const toast = useToast(); const q = ref(''); const me = useMe()
const { data, refresh } = await useAsyncData('adm-users', () => api<any[]>('/api/admin/users', { query: { q: q.value || undefined } }), { server: false })
let t: ReturnType<typeof setTimeout>; watch(q, () => { clearTimeout(t); t = setTimeout(refresh, 300) })
async function patch(u: any, body: any) { try { await api(`/api/admin/users/${u.id}`, { method: 'PATCH', body }); toast.ok('Mis à jour'); refresh() } catch (e) { toast.err(errMsg(e)) } }
</script>
<template><div class="space-y-6"><h1 class="text-[clamp(1.8rem,4vw,2.6rem)] font-black">Utilisateurs</h1><input v-model="q" type="search" class="input max-w-sm" placeholder="Rechercher par e-mail" aria-label="Rechercher">
  <div class="card overflow-x-auto"><table class="w-full min-w-[680px]"><thead><tr><th class="th">Utilisateur</th><th class="th">Rôle</th><th class="th">Statut</th><th class="th">Inscrit</th><th class="th" /></tr></thead><tbody class="divide-y divide-line"><tr v-for="u in data" :key="u.id"><td class="td">{{ u.name }}<span class="block text-xs text-muted">{{ u.email }}{{ u.verified ? '' : ' · non vérifié' }}</span></td><td class="td capitalize">{{ u.role }}</td><td class="td capitalize" :class="u.status === 'active' ? 'text-emerald-300' : 'text-red-300'">{{ u.status }}</td><td class="td text-muted">{{ fdate(u.createdAt, { dateStyle: 'medium' }) }}</td><td class="td text-right"><template v-if="u.id !== me.user?.id"><button class="btn btn-ghost !min-h-[36px] px-3" @click="patch(u, { status: u.status === 'active' ? 'suspended' : 'active' })">{{ u.status === 'active' ? 'Suspendre' : 'Réactiver' }}</button> <button class="btn btn-ghost !min-h-[36px] px-3" @click="patch(u, { platformRole: u.role === 'admin' ? 'user' : 'admin' })">{{ u.role === 'admin' ? 'Retirer admin' : 'Promouvoir admin' }}</button></template></td></tr></tbody></table></div></div></template>
